// sb-native-tests.cpp — Factory, automation state, WAV import, locks and actual native-editor tests.
#include "sb-plugin.h"
#include "sb-ui.h"
#include <iostream>
using namespace juce;
static void verify(bool result,const char* text){if(!result){std::cerr<<"FAIL: "<<text<<'\n';std::exit(1);}}
static PrismUI::MotionPanel* findMotion(Component& parent){if(auto* panel=dynamic_cast<PrismUI::MotionPanel*>(&parent))return panel;for(auto* child:parent.getChildren())if(auto* panel=findMotion(*child))return panel;return nullptr;}
static void render(PrismProcessor& p,int blocks,bool notes=true){AudioBuffer<float> b(2,256);MidiBuffer midi;double energy=0;for(int block=0;block<blocks;++block){midi.clear();if(block==0&&notes)for(int n:{48,55,60})midi.addEvent(MidiMessage::noteOn(1,n,.8f),0);if(block==blocks*3/4)midi.addEvent(MidiMessage::allNotesOff(1),0);p.processBlock(b,midi);for(int c=0;c<2;++c)for(int s=0;s<256;++s){float v=b.getSample(c,s);verify(std::isfinite(v)&&std::abs(v)<.65f,"native output is finite and bounded");energy+=v*v;}}if(notes)verify(energy>1.e-12,"native patch produces audio");}
int main(int argc,char** argv){
 ScopedJuceInitialiser_GUI gui;PrismProcessor p;p.prepareToPlay(48000,256);verify(p.factoryCount()==117,"116 recipes + init");const auto& schema=SynthB::Schema::get();
 for(int n=0;n<p.factoryCount();++n){verify(p.restore(p.factoryPatch(n)).wasOk(),"factory validates");auto original=p.patch();MemoryBlock saved;p.getStateInformation(saved);p.write("osc1.pos",.991f);p.setStateInformation(saved.getData(),int(saved.getSize()));auto restored=p.patch();for(const auto& spec:schema.specs){Identifier key(String(spec.key));float a=float(original["params"][key]),b=float(restored["params"][key]);verify(std::abs(spec.unitValue(a)-spec.unitValue(b))<.00002f,"parameter round trip");}verify(original["name"]==restored["name"]&&original["macros"]==restored["macros"],"metadata round trip");render(p,40);}
 auto sparse=JSON::parse(R"({"format":"dualsynth-patch","engine":"B","version":1,"params":{},"mod":[{"src":"LFO 1","dst":"osc1.pos","amount":0.3,"bipolar":false,"curve":2}],"fx":[{"type":"Reverb","on":true,"params":{"mix":0.7,"mode":2}}]})");verify(p.restore(sparse).wasOk(),"descriptive patch import");verify(p.read("mod1.bipolar")==0&&p.read("mod1.curve")==2&&std::abs(p.read("fx5.mix")-.7f)<.00001f,"descriptive route and FX fields");
 p.selectFactory(0);p.write("rack.slot2",0);verify(p.restore(p.patch()).wasOk(),"duplicate rack selection state round trip");
 auto before=JSON::toString(p.patch(),true);auto bad=p.patch();bad["params"].getDynamicObject()->setProperty("flt1.cutoff",-1);verify(p.restore(bad).failed(),"reject invalid patch");verify(JSON::toString(p.patch(),true)==before,"invalid patch is atomic");
 p.selectFactory(1);p.write(schema.loc.locks[0],1);std::array<float,40> locked{};for(int i=0;i<40;++i)locked[size_t(i)]=p.read(i);p.randomize();for(int i=0;i<40;++i)verify(locked[size_t(i)]==p.read(i),"oscillator lock is honored");
 p.selectFactory(0);p.route(4,schema.loc.osc[0]+SynthB::pos);verify(p.read(schema.loc.route[0])==4&&p.read(schema.loc.route[0]+1)==float(schema.loc.osc[0]+SynthB::pos+1),"drop route creation");p.reorder(0,9);verify(p.read(schema.loc.order[9])==0&&p.read(schema.loc.order[0])==1,"rack reorder");
 File scratch=File::getCurrentWorkingDirectory().getChildFile("work");scratch.createDirectory();TemporaryFile waveFile(scratch.getChildFile("sb-import-validation.wav"));AudioBuffer<float> sine(1,2048);for(int n=0;n<2048;++n)sine.setSample(0,n,std::sin(float(SynthB::tau*n/2048)));{
 auto output=waveFile.getFile().createOutputStream();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(wav.createWriterFor(output.release(),48000,1,24,{},0));verify(bool(writer),"temporary WAV writer");writer->writeFromAudioSampleBuffer(sine,0,2048);}
 verify(p.importWave(waveFile.getFile(),0).wasOk(),"WAV import");verify(p.importedTable()!=nullptr&&p.read("osc1.table")==30,"WAV is selected");auto imported=p.patch();verify(imported.hasProperty("wavetable"),"embedded table in JSON");p.selectFactory(0);verify(p.importedTable()==nullptr,"factory clears custom asset");verify(p.restore(imported).wasOk()&&p.importedTable()!=nullptr,"embedded asset recall");render(p,40);
 for(int cycle:{0,512,1024,2048}){verify(p.importWave(waveFile.getFile(),1,cycle).wasOk(),"WAV frame mode");verify(p.importedTable()->frames==(cycle==0?1:2048/cycle),"import frame count");render(p,8);}
 for(double sr:{44100.,96000.}){p.selectFactory(1);p.prepareToPlay(sr,512);for(int size:{1,31,127,512,1024}){AudioBuffer<float> block(2,size);MidiBuffer midi;midi.addEvent(MidiMessage::noteOn(1,60,.8f),size-1);p.processBlock(block,midi);for(int c=0;c<2;++c)for(int i=0;i<size;++i)verify(std::isfinite(block.getSample(c,i)),"sample rate and block size");}p.silence.store(true);}p.prepareToPlay(48000,256);
 if(argc>1){File directory=File::getCurrentWorkingDirectory().getChildFile(argv[1]);directory.createDirectory();p.selectFactory(2);render(p,20);for(int width:{1000,1280,1600}){std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());editor->setSize(width,width*9/16);auto image=editor->createComponentSnapshot(editor->getLocalBounds(),true);auto output=directory.getChildFile("Prism-Flux-"+String(width)+".png").createOutputStream();verify(bool(output),"screenshot file");output->setPosition(0);output->truncate();PNGImageFormat png;verify(png.writeImageToStream(image,*output),"native screenshot");}
  {std::unique_ptr<AudioProcessorEditor> editor(p.createEditor());auto* motion=findMotion(*editor);verify(motion!=nullptr,"motion panel exists");for(int tab=1;tab<4;++tab){motion->choose(tab);auto image=editor->createComponentSnapshot(editor->getLocalBounds(),true);auto output=directory.getChildFile("Prism-Flux-tab-"+String(tab)+".png").createOutputStream();verify(bool(output),"tab screenshot file");output->setPosition(0);output->truncate();PNGImageFormat png;verify(png.writeImageToStream(image,*output),"tab snapshot");}}
  auto output=directory.getChildFile("Prism-Flux-demo.wav").createOutputStream();output->setPosition(0);output->truncate();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(wav.createWriterFor(output.release(),48000,2,24,{},0));verify(bool(writer),"demo writer");AudioBuffer<float> b(2,256);MidiBuffer midi;
  for(int preset:{1,15,29,43,71,85,95}){p.selectFactory(preset);for(int block=0;block<1125;++block){midi.clear();bool pulse=preset==1||preset==29||preset==85;if((!pulse&&block==0)||(pulse&&block<750&&block%94==0))for(int n:{48,55,60,63})midi.addEvent(MidiMessage::noteOn(1,n,.8f),0);if(block==750||(pulse&&block%94==47))midi.addEvent(MidiMessage::allNotesOff(1),0);p.processBlock(b,midi);writer->writeFromAudioSampleBuffer(b,0,256);}}
 }
 std::cout<<"PASS: 117 factory recipes, native audio, host/JSON recall, invalid-patch atomicity, locked randomizer, route creation, rack reorder, four WAV import modes and embedded-table recall, 44.1/48/96 kHz, variable block sizes, native editor lifecycle.\n";
}
